package com.orderflow.notification.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notification_preference")public class NotificationPreference{@Id@Column(name="user_id")private UUID userId;@Column(name="email_enabled",nullable=false)private boolean emailEnabled;@Column(name="sms_enabled",nullable=false)private boolean smsEnabled;@Column(name="email_address",length=254)private String emailAddress;@Column(name="phone_number",length=32)private String phoneNumber;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected NotificationPreference(){}public static NotificationPreference defaults(UUID user,Instant now){NotificationPreference p=new NotificationPreference();p.userId=user;p.updatedAt=now;return p;}public void update(boolean email,String address,boolean sms,String phone,Instant now){if(email&&(address==null||!address.matches("^[^@\\s]{1,64}@[^@\\s]{1,189}$")))throw new IllegalArgumentException("Valid email is required");if(sms&&(phone==null||!phone.matches("^\\+[1-9][0-9]{7,14}$")))throw new IllegalArgumentException("Valid phone is required");emailEnabled=email;emailAddress=email?address:null;smsEnabled=sms;phoneNumber=sms?phone:null;updatedAt=now;}public UUID getUserId(){return userId;}public boolean isEmailEnabled(){return emailEnabled;}public boolean isSmsEnabled(){return smsEnabled;}public String getEmailAddress(){return emailAddress;}public String getPhoneNumber(){return phoneNumber;}public Instant getUpdatedAt(){return updatedAt;}public long getVersion(){return version;}}
